import numpy as np
z=np.load('source_pixels.npz')['rgb']
# per-pixel movement mask and connected components at threshold from bg
bg=np.median(z[:35],axis=0)
def comps(mask):
 h,w=mask.shape; seen=np.zeros_like(mask,bool); out=[]
 for y,x in zip(*np.where(mask & ~seen)):
  if seen[y,x]: continue
  st=[(y,x)]; seen[y,x]=1; pts=[]
  while st:
   yy,xx=st.pop(); pts.append((yy,xx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     ny,nx=yy+dy,xx+dx
     if 0<=ny<h and 0<=nx<w and mask[ny,nx] and not seen[ny,nx]: seen[ny,nx]=1; st.append((ny,nx))
  if len(pts)>=2: out.append(pts)
 return out
for fi in [0,20,35,38,40,42,44,46,48,50,52,54,56,60,64,68,72,80,88,95]:
 d=np.abs(z[fi].astype(np.float32)-bg).max(2)
 m=(d>45)
 m[:65]=0;m[120:]=0;m[:,:90]=0;m[:,166:]=0
 cc=comps(m)
 desc=[]
 for p in sorted(cc,key=len,reverse=True)[:5]:
  ys=[a for a,b in p];xs=[b for a,b in p];desc.append((len(p),(min(xs),min(ys),max(xs),max(ys))))
 print(fi,desc)
PY"

